INSERT INTO official_accounts VALUES ('acct_pharm_exam','省执业药师考试办公室','考试报名','省级执业药师职业资格考试组织机构，发布报名、资格审核、考务与证书事项公告。');
INSERT INTO official_accounts VALUES ('acct_prov_mpa','省药品监督管理局','行业监管','发布药品经营质量管理、执业药师注册与在岗履职相关的监管要求和抽查通报。');
INSERT INTO official_accounts VALUES ('acct_ce_platform','执业药师继续教育服务平台','继续教育','承担本省执业药师继续教育选课、学时登记与证明打印服务。');
INSERT INTO official_account_subscriptions VALUES ('user_zhou','acct_pharm_exam','2025-08-01T21:40:00+08:00');
