INSERT INTO official_account_posts VALUES ('post_pharm_exam_001','acct_pharm_exam','关于开展 2025 年度执业药师注册信息核查的通知','对全省已注册执业药师的执业单位、在岗状态与联系方式开展年度核查，逾期未确认的将暂停注册状态。','https://notice.pharm-exam.example.test/posts/post_pharm_exam_001','2026-04-03T16:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_pharm_exam_002','acct_pharm_exam','2025 年度执业药师资格考试合格证书发放安排','合格证书自 3 月 10 日起由各市考试机构发放，本人凭身份证原件领取，可委托他人代领但须提供授权书。','https://notice.pharm-exam.example.test/posts/post_pharm_exam_002','2026-04-04T15:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_pharm_exam_003','acct_pharm_exam','关于启用新版报名系统的公告','新版报名系统已上线，支持人脸核身与学历在线核验，旧系统账号需重新绑定手机号后继续使用。','https://notice.pharm-exam.example.test/posts/post_pharm_exam_003','2026-04-05T04:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_pharm_exam_004','acct_pharm_exam','执业药师职业资格考试考区设置说明','全省设 13 个考区，考生按报名时选择的考区参加考试，报名结束后原则上不再受理考区变更。','https://notice.pharm-exam.example.test/posts/post_pharm_exam_004','2026-04-05T21:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_pharm_exam_005','acct_pharm_exam','关于考试用书发行渠道的声明','本办公室不指定、不委托任何机构发行考试用书或培训课程，请考生通过正规渠道购买。','https://notice.pharm-exam.example.test/posts/post_pharm_exam_005','2026-04-07T10:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_pharm_exam_006','acct_pharm_exam','2026 年度考试工作计划公布','2026 年执业药师职业资格考试拟定于 10 月中旬举行，具体报名时间以后续通知为准。','https://notice.pharm-exam.example.test/posts/post_pharm_exam_006','2026-04-08T05:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_pharm_exam_007','acct_pharm_exam','关于报名照片规格的说明','报名照片须为近 6 个月内白底免冠正面证件照，像素不低于 295×413，由系统自动检测，不合规将被退回。','https://notice.pharm-exam.example.test/posts/post_pharm_exam_007','2026-04-09T12:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_pharm_exam_008','acct_pharm_exam','考试违纪违规行为处理办法要点提示','携带、传递试题或答案，由他人代考或代他人考试的，成绩无效并记入专业技术人员资格考试诚信档案库。','https://notice.pharm-exam.example.test/posts/post_pharm_exam_008','2026-04-10T07:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_pharm_exam_009','acct_pharm_exam','关于工作年限计算口径的答疑','工作年限计算截止日期为考试当年 12 月 31 日，全日制学历在校学习期间不计入相关专业工作年限。','https://notice.pharm-exam.example.test/posts/post_pharm_exam_009','2026-04-10T20:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_pharm_exam_010','acct_pharm_exam','学历核验未通过的处理流程','学历信息在线核验未通过的考生，须在资格审核阶段提交学历认证报告，认证渠道为学信网。','https://notice.pharm-exam.example.test/posts/post_pharm_exam_010','2026-04-11T19:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_pharm_exam_011','acct_pharm_exam','关于成绩有效期的政策提示','考试成绩实行 4 年为一个周期的滚动管理办法，参加全部科目考试的人员须在连续 4 个考试年度内通过全部科目。','https://notice.pharm-exam.example.test/posts/post_pharm_exam_011','2026-04-12T18:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_pharm_exam_012','acct_pharm_exam','免试部分科目的申请条件','符合免试条件的人员须在报名时选择相应报考级别，并在资格审核时提交职称证书原件核验。','https://notice.pharm-exam.example.test/posts/post_pharm_exam_012','2026-04-13T11:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_pharm_exam_013','acct_pharm_exam','关于考试收费标准的公告','考务费按每人每科 61 元收取，四科合计 244 元，由省财政厅、省发展改革委核定，通过报名系统在线缴纳。','https://notice.pharm-exam.example.test/posts/post_pharm_exam_013','2026-04-15T00:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_pharm_exam_014','acct_pharm_exam','考生诚信档案库查询入口开通','考生可通过全国专业技术人员资格考试报名服务平台查询本人诚信记录，如有异议可向报名地考试机构申诉。','https://notice.pharm-exam.example.test/posts/post_pharm_exam_014','2026-04-15T19:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_pharm_exam_015','acct_pharm_exam','关于加强考试期间疫情防控的通知','考生须自备口罩，进入考点接受体温检测，体温异常者由考点安排至备用考场。','https://notice.pharm-exam.example.test/posts/post_pharm_exam_015','2026-04-17T08:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_pharm_exam_016','acct_pharm_exam','2025 年度考试合格标准公布','四个科目合格标准均为试卷满分的 60%，即 72 分（试卷满分 120 分）。','https://notice.pharm-exam.example.test/posts/post_pharm_exam_016','2026-04-18T15:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_pharm_exam_017','acct_pharm_exam','关于报名信息填报错误的更正说明','报名信息提交后，考生姓名、身份证号不得自行修改，其余信息在报名截止前可自行更正。','https://notice.pharm-exam.example.test/posts/post_pharm_exam_017','2026-04-19T10:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_pharm_exam_018','acct_pharm_exam','考区咨询电话公布','各考区设置报名咨询电话，工作日 9:00-12:00、14:00-17:00 接听，具体号码见附件。','https://notice.pharm-exam.example.test/posts/post_pharm_exam_018','2026-04-20T15:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_pharm_exam_019','acct_pharm_exam','关于电子证书上线的通知','2024 年及以后取得的资格证书已同步至全国专业技术人员职业资格证书查询验证系统，可下载电子证书。','https://notice.pharm-exam.example.test/posts/post_pharm_exam_019','2026-04-22T04:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_pharm_exam_020','acct_pharm_exam','考试大纲修订说明','2026 年度考试大纲已完成修订，药事管理与法规科目变动较大，其余三科保持稳定。','https://notice.pharm-exam.example.test/posts/post_pharm_exam_020','2026-04-22T23:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_pharm_exam_021','acct_pharm_exam','关于打印准考证的一般性提示','准考证一般于考前一周开放打印，考生须凭准考证和有效居民身份证参加考试，两证缺一不可。','https://notice.pharm-exam.example.test/posts/post_pharm_exam_021','2026-04-24T04:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_prov_mpa_022','acct_prov_mpa','关于开展药品零售企业执业药师在岗履职专项检查的通知','检查重点为执业药师是否在岗在职、处方审核记录是否完整、是否存在挂证行为。','https://notice.pharm-exam.example.test/posts/post_prov_mpa_022','2026-04-25T17:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_prov_mpa_023','acct_prov_mpa','药品经营质量管理规范实施情况通报（第一季度）','抽查 218 家零售企业，发现处方药销售记录不完整 37 家，已责令限期整改。','https://notice.pharm-exam.example.test/posts/post_prov_mpa_023','2026-04-26T06:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_prov_mpa_024','acct_prov_mpa','关于严禁执业药师挂证行为的公告','执业药师注册单位与实际工作单位不一致的，一经查实注销其注册证书并列入失信名单。','https://notice.pharm-exam.example.test/posts/post_prov_mpa_024','2026-04-27T11:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_prov_mpa_025','acct_prov_mpa','药品追溯体系建设阶段性要求','2026 年起，药品零售企业须实现疫苗、麻醉药品、精神药品的全品种追溯数据上传。','https://notice.pharm-exam.example.test/posts/post_prov_mpa_025','2026-04-28T10:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_prov_mpa_026','acct_prov_mpa','关于处方流转平台接入的指导意见','鼓励零售药店接入省级处方流转平台，接入企业须配备具有处方审核资质的执业药师。','https://notice.pharm-exam.example.test/posts/post_prov_mpa_026','2026-04-29T15:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_prov_mpa_027','acct_prov_mpa','零售药店分级分类管理实施方案','按经营范围和管理能力将零售药店分为三类，二类以上须配备至少 1 名执业药师。','https://notice.pharm-exam.example.test/posts/post_prov_mpa_027','2026-04-30T14:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_prov_mpa_028','acct_prov_mpa','关于中药饮片质量抽检结果的通报','本季度抽检中药饮片 460 批次，不合格 12 批次，主要问题为含量测定不符合规定。','https://notice.pharm-exam.example.test/posts/post_prov_mpa_028','2026-05-02T03:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_prov_mpa_029','acct_prov_mpa','药品网络销售监督管理有关要求','从事药品网络零售的企业须依法取得药品经营许可证，处方药销售须实现处方来源可查。','https://notice.pharm-exam.example.test/posts/post_prov_mpa_029','2026-05-03T08:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_prov_mpa_030','acct_prov_mpa','关于开展药品安全巩固提升行动的通知','行动持续至年底，重点整治药品经营环节非法渠道购销、执业药师挂证等问题。','https://notice.pharm-exam.example.test/posts/post_prov_mpa_030','2026-05-04T15:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_prov_mpa_031','acct_prov_mpa','执业药师注册管理有关事项的说明','执业药师注册有效期为 5 年，需在有效期届满 30 日前申请延续注册。','https://notice.pharm-exam.example.test/posts/post_prov_mpa_031','2026-05-05T10:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_ce_platform_032','acct_ce_platform','2026 年度执业药师继续教育选课开放','本年度继续教育共开设专业科目 42 门、公需科目 8 门，学员可按执业方向自主选课。','https://notice.pharm-exam.example.test/posts/post_ce_platform_032','2026-05-05T23:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_ce_platform_033','acct_ce_platform','关于继续教育学时要求的说明','执业药师每年须完成不少于 90 学时的继续教育，其中专业科目不少于 60 学时。','https://notice.pharm-exam.example.test/posts/post_ce_platform_033','2026-05-06T18:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_ce_platform_034','acct_ce_platform','继续教育证明打印功能上线','完成本年度学时的学员可自行下载电子版继续教育证明，加盖电子印章，与纸质版具有同等效力。','https://notice.pharm-exam.example.test/posts/post_ce_platform_034','2026-05-08T07:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_ce_platform_035','acct_ce_platform','新增课程：处方审核实务与案例分析','课程共 12 学时，结合真实处方案例讲解审核要点，适合零售药店在岗人员。','https://notice.pharm-exam.example.test/posts/post_ce_platform_035','2026-05-09T00:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_ce_platform_036','acct_ce_platform','关于学时补修的通知','往年学时未修满的学员可在本年度补修，补修学时计入原年度，不占用本年度学时。','https://notice.pharm-exam.example.test/posts/post_ce_platform_036','2026-05-10T13:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_ce_platform_037','acct_ce_platform','平台系统维护公告','平台将于每周二 0:00-6:00 进行例行维护，维护期间选课与学时登记功能暂停使用。','https://notice.pharm-exam.example.test/posts/post_ce_platform_037','2026-05-11T12:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_ce_platform_038','acct_ce_platform','新增课程：药物警戒与不良反应上报','课程共 8 学时，讲解药品不良反应监测要求与上报流程。','https://notice.pharm-exam.example.test/posts/post_ce_platform_038','2026-05-13T01:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_ce_platform_039','acct_ce_platform','关于线下面授班次安排的通知','本年度在全省 6 个市设置线下面授点，每期 40 人，报满为止。','https://notice.pharm-exam.example.test/posts/post_ce_platform_039','2026-05-13T18:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_ce_platform_040','acct_ce_platform','学时数据同步说明','学时数据每月 5 日与省药品监督管理局注册系统同步一次，同步后不可撤销。','https://notice.pharm-exam.example.test/posts/post_ce_platform_040','2026-05-15T01:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_ce_platform_041','acct_ce_platform','关于课程回看期限的提示','已购课程在本年度 12 月 31 日前可无限次回看，逾期系统将关闭访问入口。','https://notice.pharm-exam.example.test/posts/post_ce_platform_041','2026-05-15T20:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_pharm_exam_042','acct_pharm_exam','零售终端用药咨询能力提升培训回顾','本期培训覆盖慢病用药、儿童剂量换算与老年人多重用药，参训 751 人，考核合格率 69%。','https://notice.pharm-exam.example.test/posts/post_pharm_exam_042','2026-05-17T03:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_pharm_exam_043','acct_pharm_exam','关于12月份药品价格监测情况的通报','监测品种 260 个，其中价格上涨 36 个、下降 27 个，整体波动幅度在合理区间。','https://notice.pharm-exam.example.test/posts/post_pharm_exam_043','2026-05-18T10:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_ce_platform_044','acct_ce_platform','药品不良反应监测季度分析','本季度收到报告 758 份，其中新的和严重的报告占比 95%，主要涉及抗菌药物与心血管用药。','https://notice.pharm-exam.example.test/posts/post_ce_platform_044','2026-05-19T03:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_ce_platform_045','acct_ce_platform','关于8月药品抽检结果的公示','共抽检 216 批次，合格 79 批次，不合格品种及企业名单见附件。','https://notice.pharm-exam.example.test/posts/post_ce_platform_045','2026-05-20T16:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_prov_mpa_046','acct_prov_mpa','基本药物配备使用情况调度','全省零售药店基本药物配备品规数中位数为 279 个，较上季度增加 32 个。','https://notice.pharm-exam.example.test/posts/post_prov_mpa_046','2026-05-21T09:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_prov_mpa_047','acct_prov_mpa','关于加强特殊管理药品管理的提示','4月排查发现麻醉药品专用处方保存不规范 70 家，均已整改到位。','https://notice.pharm-exam.example.test/posts/post_prov_mpa_047','2026-05-21T22:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_pharm_exam_048','acct_pharm_exam','执业药师配备情况月度统计','全省在册执业药师 596 人，其中零售企业执业 53 人，医疗机构执业 7 人。','https://notice.pharm-exam.example.test/posts/post_pharm_exam_048','2026-05-23T11:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_prov_mpa_049','acct_prov_mpa','关于处方药与非处方药分类管理的提醒','8月检查中发现处方药开架销售 3 家，已依法处理并要求整改。','https://notice.pharm-exam.example.test/posts/post_prov_mpa_049','2026-05-24T06:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_prov_mpa_050','acct_prov_mpa','药学服务规范化建设试点进展','首批 347 家试点药店已完成药学服务区改造，配备用药咨询台与私密咨询空间。','https://notice.pharm-exam.example.test/posts/post_prov_mpa_050','2026-05-25T01:00:00+08:00');
INSERT INTO official_account_posts VALUES ('post_ce_platform_051','acct_ce_platform','关于医保定点药店药品追溯的工作提示','1月起，医保定点药店销售的追溯品种须扫码上传，未上传的暂缓结算。','https://notice.pharm-exam.example.test/posts/post_ce_platform_051','2026-05-26T14:00:00+08:00');
